#include <iostream>

int main() {
    char first_word[30];
    std::cin >> first_word;
    std::cout << "Word via >>: [" << first_word << "]\n";

    // Peek at next character without removing it
    int next_char = std::cin.peek();
    std::cout << "Next char via peek: '" << static_cast<char>(next_char) << "'\n";

    // Read the rest using cin.get(buffer, size)
    char rest_line[80];
    std::cin.get(rest_line, sizeof(rest_line));
    std::cout << "Rest via get: [" << rest_line << "]\n";

    // Observe delimiter \n is still present in stream; ignore it
    if (std::cin.peek() == '\n') {
        std::cin.ignore(1, '\n');
    }

    // Use putback to simulate inspecting and returning a prefix
    char ch = static_cast<char>(std::cin.get());
    std::cout << "Read char: '" << ch << "'\n";
    std::cin.putback(ch);

    // Read full second line with getline
    char second_line[80];
    std::cin.getline(second_line, sizeof(second_line));
    std::cout << "Line via getline: [" << second_line << "]\n";

    return 0;
}

#include <iostream>

int main() {
    constexpr int CHUNK_SIZE = 12;
    char buffer[32]{};

    std::cout << "Reading raw bytes...\n";
    std::cin.read(buffer, CHUNK_SIZE);

    std::streamsize bytes_read = std::cin.gcount();
    std::cout << "gcount() = " << bytes_read << " bytes\n";

    std::cout << "Writing exact bytes via cout.write:\n[";
    std::cout.write(buffer, bytes_read);
    std::cout << "]\n";

    // Verify whether failbit was set (occurs when requested bytes > available bytes)
    if (std::cin.fail() && !std::cin.bad()) {
        std::cout << "Note: cin reached EOF before reading full chunk; failbit set.\n";
    }

    return 0;
}
